namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int ForCents(LoyaltyTier tier, int subtotalCents)
    {
        var effectivePoints = Math.Min(TierPoints(tier) + OrderSizePoints(subtotalCents), CeilingPoints);

        return subtotalCents * effectivePoints / 100;
    }

    private static int TierPoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };

    private static int OrderSizePoints(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int For(LoyaltyTier tier, int subtotalCents)
    {
        return subtotalCents - LoyaltyDiscount.ForCents(tier, subtotalCents);
    }
}
E
